<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { useAuthStore } from '@/stores/auth'; import { Lock, User, ArrowRight } from '@element-plus/icons-vue'
const router = useRouter(); const auth = useAuthStore(); const loading = ref(false); const form = reactive({ loginName: '', password: '' })
async function submit() { if (!form.loginName || !form.password) return ElMessage.warning('请输入企业账号和密码'); loading.value = true; try { await auth.login('enterprise', form); router.replace('/enterprise/batches') } catch (error) { ElMessage.error(error instanceof Error ? error.message : '登录失败') } finally { loading.value = false } }
</script>
<template><div class="login-screen login-screen--enterprise"><div class="login-screen__visual"><div class="login-orbit login-orbit--one"></div><div class="login-orbit login-orbit--two"></div><div class="login-visual-copy"><span class="eyebrow">NODE ENTERPRISE PORTAL</span><h1>让每一次<br><em>交接更可信。</em></h1><p>记录企业在冷链网络中的每一个动作，<br>用透明协作守护海产品品质。</p><div class="login-visual-stats"><div><strong>100%</strong><span>链路留痕</span></div><div><strong>4°C</strong><span>冷链标准</span></div><div><strong>7×24</strong><span>状态可查</span></div></div></div><div class="login-wave"></div></div><div class="login-screen__panel"><div class="login-form-wrap"><div class="login-brand"><span class="brand-mark__symbol">F</span><div><strong>FSTS</strong><small>冷链溯源中枢</small></div></div><div class="login-heading"><span class="eyebrow">ENTERPRISE PORTAL</span><h2>企业端登录</h2><p>登录后管理您的批号与进场确认。</p></div><el-form :model="form" size="large" @submit.prevent="submit"><el-form-item><el-input v-model="form.loginName" placeholder="企业登录账号" :prefix-icon="User" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="登录密码" :prefix-icon="Lock" @keyup.enter="submit" /></el-form-item><el-button type="primary" class="login-submit" :loading="loading" @click="submit">进入企业端 <el-icon><ArrowRight /></el-icon></el-button></el-form><div class="login-switch">管理员用户？<router-link to="/admin/login">切换到管理端登录</router-link></div></div></div></div></template>
